with ins as (insert into public.artist_press (artist_id,artist_slug,title,publication,url,date_published,type) select a.id,x.s,x.t,x.p,x.u,x.d::date,'feature' from json_to_recordset('[{"s":"rafiki","t":"The Mix 019: Rafiki","p":"Mixmag","u":"https://mixmag.net/feature/the-mix-019-rafiki-dj-interview-mumbai-house-techno-krunk-kulture","d":"2024-06-26"},{"s":"rafiki","t":"Rafiki - 5 AM Dub (single review)","p":"Resident Advisor","u":"https://ra.co/reviews/35687","d":"2023-09-12"},{"s":"rafiki","t":"Premiere: Rafiki, New Shifts EP, ''Walk the Talk''","p":"Mixmag Asia","u":"https://mixmag.asia/read/premiere-rafiki-new-shifts-ep-walk-the-talk-single-premiere","d":"2023-07-31"},{"s":"rafiki","t":"Rafiki and Squidworks pay tribute to Bandra on Good Luck EP","p":"Mixmag Asia","u":"https://mixmag.asia/read/rafiki-squidworks-tribute-to-mumbai-suburb-bandra-good-luck-ep-new-releases","d":"2025-06-18"}]'::json) as x(s text,t text,p text,u text,d text) join public.artists a on a.slug=x.s on conflict (artist_slug,url) do nothing returning 1) select count(*) from ins;